  function professionalRadar(wxA,wxB,nameA,nameB){const order=['木','水','金','土','火'],cx=145,cy=125,r=78,max=Math.max(3,...order.flatMap(w=>[wxA[w].count,wxB[w].count])),point=(i,v)=>{const angle=-Math.PI/2+i*Math.PI*2/5;return[(cx+Math.cos(angle)*r*v/max).toFixed(1),(cy+Math.sin(angle)*r*v/max).toFixed(1)]},rings=[1,2,3].map(k=>`<polygon points="${order.map((_,i)=>point(i,max*k/3).join(',')).join(' ')}"/>`).join(''),axes=order.map((_,i)=>{const p=point(i,max);return`<line x1="${cx}" y1="${cy}" x2="${p[0]}" y2="${p[1]}"/>`}).join(''),poly=(data,cls)=>`<polygon class="${cls}" points="${order.map((w,i)=>point(i,data[w].count).join(',')).join(' ')}"/>${order.map((w,i)=>{const p=point(i,data[w].count);return`<circle class="${cls}" cx="${p[0]}" cy="${p[1]}" r="3"/>`}).join('')}`,labels=order.map((w,i)=>{const p=point(i,max+0.48);return`<text x="${p[0]}" y="${Number(p[1])+3}" text-anchor="middle">${w}</text>`}).join('');return`<svg class="professional-radar" viewBox="0 0 290 245" role="img" aria-label="${nameA}与${nameB}五行参数对照"><g class="professional-radar-grid">${rings}${axes}</g>${poly(wxA,'person-a')}${poly(wxB,'person-b')}${labels}<g class="radar-legend"><circle class="person-a" cx="76" cy="230" r="4"/><text x="85" y="233">${nameA}</text><circle class="person-b" cx="170" cy="230" r="4"/><text x="179" y="233">${nameB}</text></g></svg>`}
